const t = $('ENTRADA (Execute Workflow Trigger)').first().json;
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

// Payload para v3.revision.ejecutar_revision() (Python, unica autoridad:
// invoca correcciones_tiquipaya.py + pipeline_tiquipaya.procesar_cierre_con_correccion()
// de V2 sin cambios). Este nodo NUNCA decide que corregir: la correccion ya
// viene decidida por el auditor humano dentro de cada item.
const payload = {
  cierres_con_correccion: t.cierres_con_correccion || [],
  base_dir_dev: t.base_dir_dev,
  version_codigo: t.version_codigo || null,
  controles_dir_dev: t.controles_dir_dev || null,
};

const rutaInputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_revision_input_' + executionId + '.json';
const rutaOutputTmp = '/home/codespace/.n8n-files/tiq_v3_tmp/tiq_v3_revision_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];
